<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f6f8fc;
      --surface: rgba(255, 255, 255, 0.92);
      --surface-strong: #ffffff;
      --text: #10233f;
      --muted: #5b6780;
      --border: #d9e2f2;
      --accent: #4f46e5;
      --accent-soft: #eef2ff;
      --success: #0f766e;
      --shadow: 0 24px 60px rgba(16, 35, 63, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(79, 70, 229, 0.16), transparent 28%),
        radial-gradient(circle at top right, rgba(14, 165, 233, 0.12), transparent 26%),
        var(--bg);
      color: var(--text);
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .app-shell {
      width: min(920px, 100%);
    }

    .hero {
      background: linear-gradient(135deg, #111827, #1f2937 55%, #334155);
      color: white;
      border-radius: 28px;
      padding: 32px;
      box-shadow: var(--shadow);
      margin-bottom: 20px;
    }

    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.875rem;
      color: rgba(255, 255, 255, 0.78);
      margin-bottom: 12px;
    }

    .hero h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 3rem);
      line-height: 1.05;
    }

    .hero p {
      margin: 14px 0 0;
      max-width: 62ch;
      color: rgba(255, 255, 255, 0.8);
      font-size: 1.02rem;
      line-height: 1.6;
    }

    .quiz-card {
      background: var(--surface);
      border: 1px solid rgba(255, 255, 255, 0.8);
      border-radius: 28px;
      padding: 24px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(10px);
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      background: var(--surface-strong);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 22px;
    }

    .question-head {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 14px;
    }

    .question-title {
      margin: 0;
      font-size: 1.08rem;
      line-height: 1.4;
    }

    .help-text {
      margin: 8px 0 0;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .choice-grid {
      display: grid;
      gap: 10px;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: #fbfcff;
      transition: border-color 0.18s ease, transform 0.18s ease, background 0.18s ease;
      cursor: pointer;
    }

    .choice:hover {
      transform: translateY(-1px);
      border-color: rgba(79, 70, 229, 0.35);
      background: #f8faff;
    }

    .choice input {
      width: 18px;
      height: 18px;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice span {
      font-size: 0.98rem;
      line-height: 1.45;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      padding-top: 4px;
    }

    .submit-button {
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), #7c3aed);
      color: white;
      font: inherit;
      font-weight: 700;
      padding: 14px 22px;
      box-shadow: 0 14px 30px rgba(79, 70, 229, 0.28);
      cursor: pointer;
    }

    .submit-button:hover {
      filter: brightness(1.04);
    }

    .result {
      min-height: 1.5em;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      .hero,
      .quiz-card {
        padding: 20px;
      }

      .form-field {
        padding: 18px;
      }

      .actions {
        align-items: stretch;
      }

      .submit-button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="app-shell" id="app"></main>

  <script>
    const quizData = [
      {
        id: "languages",
        question: "Which of these are programming languages?",
        helpText: "Select every language that applies.",
        options: [
          "Python",
          "HTML",
          "JavaScript",
          "CSS"
        ]
      },
      {
        id: "paradigms",
        question: "Which languages are commonly used for general-purpose software development?",
        options: [
          "C++",
          "Java",
          "Markdown",
          "Ruby"
        ]
      },
      {
        id: "web",
        question: "Which languages are often used to build interactive web experiences?",
        options: [
          "JavaScript",
          "TypeScript",
          "SQL",
          "Bash"
        ]
      }
    ];

    function Choice(questionId, optionText, index) {
      const optionId = `${questionId}-${index}`;
      return `
        <label class="choice" for="${optionId}">
          <input id="${optionId}" type="checkbox" name="${questionId}" value="${optionText}">
          <span>${optionText}</span>
        </label>
      `;
    }

    function QuestionField({ id, question, helpText, options }) {
      return `
        <div class="form-field">
          <div class="question-head">
            <div>
              <h2 class="question-title">${question}</h2>
              ${helpText ? `<p class="help-text">${helpText}</p>` : ""}
            </div>
          </div>
          <div class="choice-grid" role="group" aria-label="${question}">
            ${options.map((option, index) => Choice(id, option, index)).join("")}
          </div>
        </div>
      `;
    }

    function App() {
      return `
        <section class="hero" aria-labelledby="quiz-title">
          <div class="hero-eyebrow">⌘ Product Quiz</div>
          <h1 id="quiz-title">Computer Languages Quiz</h1>
          <p>Choose all answers you think are correct. Each question supports multiple selections, so use every option that fits.</p>
        </section>

        <section class="quiz-card" aria-label="Quiz form">
          <form id="quiz-form" novalidate>
            ${quizData.map(QuestionField).join("")}
            <div class="actions">
              <button class="submit-button" type="submit">Submit answers</button>
              <div class="result" id="result" aria-live="polite"></div>
            </div>
          </form>
        </section>
      `;
    }

    document.getElementById("app").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const selections = quizData.map((question) => {
        const checked = Array.from(
          document.querySelectorAll(`input[name="${question.id}"]:checked`)
        ).map((input) => input.value);
        return `${question.question}: ${checked.length ? checked.join(", ") : "No selections"}`;
      });

      document.getElementById("result").textContent =
        `Submitted. ${selections.length} questions answered.`;
    });
  </script>
</body>
</html>
