<body>
  <main class="app-shell" id="app"></main>

  <script>
    const quizData = [
      {
        id: "languages",
        question: "Which of these are programming languages?",
        helpText: "Select every language that applies.",
        options: [
          "Python",
          "HTML",
          "JavaScript",
          "CSS"
        ]
      },
      {
        id: "paradigms",
        question: "Which languages are commonly used for general-purpose software development?",
        options: [
          "C++",
          "Java",
          "Markdown",
          "Ruby"
        ]
      },
      {
        id: "web",
        question: "Which languages are often used to build interactive web experiences?",
        options: [
          "JavaScript",
          "TypeScript",
          "SQL",
          "Bash"
        ]
      }
    ];

    function Choice(questionId, optionText, index) {
      const optionId = `${questionId}-${index}`;
      return `
        <label class="choice" for="${optionId}">
          <input id="${optionId}" type="checkbox" name="${questionId}" value="${optionText}">
          <span>${optionText}</span>
        </label>
      `;
    }

    function QuestionField({ id, question, helpText, options }) {
      return `
        <div class="form-field">
          <div class="question-head">
            <div>
              <h2 class="question-title">${question}</h2>
              ${helpText ? `<p class="help-text">${helpText}</p>` : ""}
            </div>
          </div>
          <div class="choice-grid" role="group" aria-label="${question}">
            ${options.map((option, index) => Choice(id, option, index)).join("")}
          </div>
        </div>
      `;
    }

    function App() {
      return `
        <section class="hero" aria-labelledby="quiz-title">
          <div class="hero-eyebrow">⌘ Product Quiz</div>
          <h1 id="quiz-title">Computer Languages Quiz</h1>
          <p>Choose all answers you think are correct. Each question supports multiple selections, so use every option that fits.</p>
        </section>

        <section class="quiz-card" aria-label="Quiz form">
          <form id="quiz-form" novalidate>
            ${quizData.map(QuestionField).join("")}
            <div class="actions">
              <button class="submit-button" type="submit">Submit answers</button>
              <div class="result" id="result" aria-live="polite"></div>
            </div>
          </form>
        </section>
      `;
    }

    document.getElementById("app").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const selections = quizData.map((question) => {
        const checked = Array.from(
          document.querySelectorAll(`input[name="${question.id}"]:checked`)
        ).map((input) => input.value);
        return `${question.question}: ${checked.length ? checked.join(", ") : "No selections"}`;
      });

      document.getElementById("result").textContent = selections.join(" • ");
    });
  </script>
</body>
</html>
